    <script>
        // 全局变量
        let characterData = {};

        // 折叠功能 - 只能展开一个顶层条目
        function toggleSection(sectionName) {
            // 先收起所有其他顶层条目
            const allSections = document.querySelectorAll('[data-section]');
            allSections.forEach(sec => {
                if (sec.dataset.section !== sectionName) {
                    sec.classList.add('collapsed');
                }
            });

            // 切换当前条目
            const section = document.querySelector(`[data-section="${sectionName}"]`);
            if (section) {
                section.classList.toggle('collapsed');
            }
        }

        // 安全地获取值的函数
        function SafeGetValue(value, defaultValue = "") {
            if (value === undefined || value === null) {
                return defaultValue;
            }
            if (Array.isArray(value)) {
                return value.length > 0 ? value[0] : defaultValue;
            }
            return value;
        }

        // 初始化显示
        async function initDisplay() {
            try {
                if (typeof getCurrentMessageId !== 'function' || typeof getChatMessages !== 'function') {
                    console.warn("SillyTavern API functions not found. Using example data.");
                    characterData = getExampleData();
                    populateWithCharacterData();
                    return;
                }

                const currentMessageId = getCurrentMessageId();
                const message_data_array = await getChatMessages(currentMessageId);

                if (!message_data_array || message_data_array.length === 0) {
                    console.error("No message data returned for ID:", currentMessageId);
                    setAllFieldsToDefault();
                    return;
                }

                const gameData = message_data_array[0].data;

                if (!gameData) {
                    console.error("Message data does not contain 'data' field.");
                    setAllFieldsToDefault();
                    return;
                }

                characterData = gameData.stat_data;
                if (!characterData && gameData.display_data) {
                    console.warn("Using display_data as fallback.");
                    characterData = gameData.display_data;
                }

                if (!characterData) {
                    console.log("No character data found. Using defaults.");
                    setAllFieldsToDefault();
                    return;
                }

                populateWithCharacterData();

            } catch (error) {
                console.error("初始化显示时出错:", error);
                setAllFieldsToDefault();
            }
        }

        // 填充角色数据
        function populateWithCharacterData() {
            if (!characterData) {
                setAllFieldsToDefault();
                return;
            }

            // 更新团队概况
            updateElement('current-date', SafeGetValue(characterData["当前日期"], "未知日期"));
            updateElement('current-time', SafeGetValue(characterData["当前时间"], "未知时间"));
            updateElement('current-location', SafeGetValue(characterData["当前地点"], "未知地点"));

            const eventName = SafeGetValue(characterData["当前事件"]?.["事件名称"], "无事件");
            const eventDay = SafeGetValue(characterData["当前事件"]?.["进行天数"], "0");
            updateElement('current-event', `${eventName} (第${eventDay}天)`);

            updateElement('team-reputation', SafeGetValue(characterData["团队状态"]?.["团队声望"], "未知"));
            updateElement('team-opinion', SafeGetValue(characterData["团队状态"]?.["团队舆论"], "未知"));

            // 更新成员数据
            renderMembers(characterData);
            renderRelationships(characterData);
            renderSchedule(characterData);

            // 显示内容，隐藏加载提示
            document.getElementById('loading').style.display = 'none';
            document.getElementById('content').style.display = 'block';
        }

        // 更新元素内容
        function updateElement(id, value) {
            const element = document.getElementById(id);
            if (element) {
                element.textContent = value;
            }
        }

        // 成员展开/收起功能
        function toggleMember(memberName) {
            // 先收起所有其他成员
            const allMembers = document.querySelectorAll('.member-item');
            allMembers.forEach(item => {
                if (item.dataset.member !== memberName) {
                    item.classList.remove('expanded');
                }
            });

            // 切换当前成员
            const currentMember = document.querySelector(`[data-member="${memberName}"]`);
            if (currentMember) {
                currentMember.classList.toggle('expanded');
            }
        }

        // 渲染成员信息
        function renderMembers(data) {
            const members = ['蔚向晚', '岑寂', '安可乐', '舒窈', '明昭雪', '空山灵', '时雨', '泠弦'];
            const memberIcons = {
                '蔚向晚': '👑',
                '岑寂': '🎭', 
                '安可乐': '🎉',
                '舒窈': '🌸',
                '明昭雪': '🎪',
                '空山灵': '🌙',
                '时雨': '🌧️',
                '泠弦': '🎵'
            };

            const membersGrid = document.getElementById('members-grid');
            membersGrid.innerHTML = '';

            members.forEach((memberName, index) => {
                const memberData = data.偶像成员?.[memberName] || {};

                const rank = SafeGetValue(memberData.排位, index + 1);
                const affection = SafeGetValue(memberData.好感度_user, '--');
                const reputation = SafeGetValue(memberData.个人声望, '--');
                const scandal = SafeGetValue(memberData.绯闻指数, '--');
                const emotion = SafeGetValue(memberData.当前情绪, '未知');

                const item = document.createElement('div');
                item.className = `member-item rank-${rank}`;
                item.dataset.member = memberName;

                item.innerHTML = `
                    <div class="member-header" onclick="toggleMember('${memberName}')">
                        <div class="member-summary">
                            <div class="member-name">${memberIcons[memberName]} ${memberName}</div>
                            <div class="member-rank">第${rank}位</div>
                            <div class="member-quick-stats">
                                <div class="quick-stat">💖${affection}</div>
                                <div class="quick-stat">⭐${reputation}</div>
                            </div>
                        </div>
                        <div class="member-expand-btn">▼</div>
                    </div>
                    <div class="member-details">
                        <div class="stats-row">
                            <div class="stat-item">
                                <span class="stat-label">💖 对你好感</span>
                                <span class="stat-value">${affection}/100</span>
                            </div>
                            <div class="stat-item">
                                <span class="stat-label">⭐ 个人声望</span>
                                <span class="stat-value">${reputation}</span>
                            </div>
                        </div>
                        <div class="stats-row">
                            <div class="stat-item">
                                <span class="stat-label">💥 绯闻指数</span>
                                <span class="stat-value">${scandal}/100</span>
                            </div>
                            <div class="stat-item">
                                <span class="stat-label">😊 当前情绪</span>
                                <span class="stat-value">${emotion}</span>
                            </div>
                        </div>
                    </div>
                `;

                membersGrid.appendChild(item);
            });
        }

        // 获取成员间关系值
        function getRelationship(data, from, to) {
            try {
                return SafeGetValue(data.偶像成员?.[from]?.队内人际关系?.[to], 10);
            } catch (e) {
                return 10;
            }
        }

        // 渲染关系分析
        function renderRelationships(data) {
            const relationshipsDiv = document.getElementById('team-relationships');

            if (!data.偶像成员) {
                relationshipsDiv.innerHTML = '<p style="text-align: center; color: #666; font-size: 0.95em; padding: 20px;">团队关系系统尚未初始化</p>';
                return;
            }

            const members = ['蔚向晚', '岑寂', '时雨', '舒窈', '明昭雪', '空山灵', '安可乐', '泠弦'];

            // 构建关系矩阵
            const relationshipMatrix = {};
            members.forEach(member => {
                relationshipMatrix[member] = {};
                members.forEach(other => {
                    if (member !== other) {
                        relationshipMatrix[member][other] = getRelationship(data, member, other);
                    }
                });
            });

            // 查找核心小团体（互相好感≥40）
            const coreGroups = [];
            const processed = new Set();

            members.forEach(member => {
                if (processed.has(member)) return;

                const closeConnections = members.filter(other => 
                    other !== member && 
                    relationshipMatrix[member][other] >= 40 && 
                    relationshipMatrix[other][member] >= 40
                );

                if (closeConnections.length > 0) {
                    const group = new Set([member]);

                    closeConnections.forEach(candidate => {
                        if (processed.has(candidate)) return;

                        let canJoin = true;
                        for (let groupMember of group) {
                            if (relationshipMatrix[candidate][groupMember] < 40 || 
                                relationshipMatrix[groupMember][candidate] < 40) {
                                canJoin = false;
                                break;
                            }
                        }

                        if (canJoin) {
                            group.add(candidate);
                        }
                    });

                    if (group.size >= 2) {
                        const groupArray = Array.from(group);
                        const avgAffections = [];

                        for (let i = 0; i < groupArray.length; i++) {
                            for (let j = i + 1; j < groupArray.length; j++) {
                                const member1 = groupArray[i];
                                const member2 = groupArray[j];
                                const avg = Math.round((relationshipMatrix[member1][member2] + 
                                                      relationshipMatrix[member2][member1]) / 2);
                                avgAffections.push(avg);
                            }
                        }

                        coreGroups.push({
                            members: groupArray.sort(),
                            avgAffection: Math.round(avgAffections.reduce((a, b) => a + b, 0) / avgAffections.length),
                            size: group.size
                        });

                        groupArray.forEach(m => processed.add(m));
                    }
                }
            });

            // 查找依附关系（单方面高好感）
            const attachmentRelations = [];
            const conflictPairs = [];
            const processedPairs = new Set();

            for (let i = 0; i < members.length; i++) {
                for (let j = i + 1; j < members.length; j++) {
                    const member1 = members[i];
                    const member2 = members[j];
                    const pairKey = [member1, member2].sort().join('-');

                    if (processedPairs.has(pairKey)) continue;

                    const affection1to2 = relationshipMatrix[member1][member2];
                    const affection2to1 = relationshipMatrix[member2][member1];

                    // 对立关系（互相负好感）
                    if (affection1to2 < 0 && affection2to1 < 0) {
                        conflictPairs.push({
                            pair: [member1, member2],
                            avg: Math.round((affection1to2 + affection2to1) / 2)
                        });
                    }
                    // 依附关系（单方面高好感）
                    else if ((affection1to2 >= 40 && affection2to1 < 20) || 
                             (affection2to1 >= 40 && affection1to2 < 20)) {
                        const from = affection1to2 > affection2to1 ? member1 : member2;
                        const to = affection1to2 > affection2to1 ? member2 : member1;
                        const intensity = Math.max(affection1to2, affection2to1);
                        attachmentRelations.push({
                            from: from,
                            to: to,
                            intensity: intensity
                        });
                    }

                    processedPairs.add(pairKey);
                }
            }

            // 生成HTML
            let relationshipHTML = '';

            // 核心小团体
            if (coreGroups.length > 0) {
                relationshipHTML += `
                    <div class="relationship-section">
                        <div class="relationship-header core">🌟 核心小团体</div>
                `;

                coreGroups.slice(0, 3).forEach((group, index) => {
                    relationshipHTML += `
                        <div class="relationship-item core">
                            <div class="relationship-content">团体 ${index + 1}: ${group.members.join(' ↔ ')}</div>
                            <div class="relationship-description">${group.size}人团体，平均好感度 ${group.avgAffection}，互相信任度极高</div>
                        </div>
                    `;
                });

                relationshipHTML += `</div>`;
            }

            // 依附关系
            if (attachmentRelations.length > 0) {
                relationshipHTML += `
                    <div class="relationship-section">
                        <div class="relationship-header attachment">💫 依附关系</div>
                `;

                attachmentRelations.slice(0, 3).forEach((rel, index) => {
                    relationshipHTML += `
                        <div class="relationship-item attachment">
                            <div class="relationship-content">依附 ${index + 1}: ${rel.from} → ${rel.to}</div>
                            <div class="relationship-description">单向好感 ${rel.intensity}，可能产生"热脸贴冷屁股"的戏剧性</div>
                        </div>
                    `;
                });

                relationshipHTML += `</div>`;
            }

            // 对立关系
            if (conflictPairs.length > 0) {
                relationshipHTML += `
                    <div class="relationship-section">
                        <div class="relationship-header conflict">⚡ 对立关系</div>
                `;

                conflictPairs.slice(0, 3).forEach((rel, index) => {
                    relationshipHTML += `
                        <div class="relationship-item conflict">
                            <div class="relationship-content">对立 ${index + 1}: ${rel.pair.join(' ↔ ')}</div>
                            <div class="relationship-description">互相好感 ${rel.avg}，价值观或利益冲突，避免单独接触</div>
                        </div>
                    `;
                });

                relationshipHTML += `</div>`;
            }

            // 如果没有特殊关系
            if (coreGroups.length === 0 && attachmentRelations.length === 0 && conflictPairs.length === 0) {
                relationshipHTML = '<p style="text-align: center; color: #666; font-size: 0.95em; padding: 20px;">目前团队内部关系相对平淡，大多数成员保持普通同事关系</p>';
            }

            relationshipsDiv.innerHTML = relationshipHTML;
        }

        // 渲染日程信息
        function renderSchedule(data) {
            const scheduleDiv = document.getElementById('schedule-info');
            const currentDay = SafeGetValue(data.当前星期);
            const schedule = data.本周日程安排;

            if (!schedule || !currentDay) {
                scheduleDiv.innerHTML = '<div class="schedule-card"><p style="text-align: center; color: #666; font-style: italic;">日程系统尚未初始化</p></div>';
                return;
            }

            const dayMapping = {
                '星期一': ['周一', '周二'], '星期二': ['周二', '周三'], '星期三': ['周三', '周四'],
                '星期四': ['周四', '周五'], '星期五': ['周五', '周六'], '星期六': ['周六', '周日'],
                '星期日': ['周日', '周一']
            };

            const [today, tomorrow] = dayMapping[currentDay] || ['周一', '周二'];
            const todaySchedule = SafeGetValue(schedule[today], '暂无安排');
            const tomorrowSchedule = SafeGetValue(schedule[tomorrow], '暂无安排');

            scheduleDiv.innerHTML = `
                <div class="schedule-card">
                    <div class="schedule-day">📅 今日日程 (${currentDay})</div>
                    <p>${todaySchedule}</p>
                </div>
                <div class="schedule-card">
                    <div class="schedule-day">📅 明日日程</div>
                    <p>${tomorrowSchedule}</p>
                </div>
            `;
        }

        // 设置所有字段为默认值
        function setAllFieldsToDefault() {
            updateElement('current-date', '未知日期');
            updateElement('current-time', '未知时间');
            updateElement('current-location', '未知地点');
            updateElement('current-event', '无事件 (第0天)');
            updateElement('team-reputation', '未知');
            updateElement('team-opinion', '未知');

            const membersGrid = document.getElementById('members-grid');
            membersGrid.innerHTML = '<div style="text-align: center; color: #666; padding: 20px; font-size: 0.9em;"><p>暂无成员数据</p></div>';

            const relationshipsDiv = document.getElementById('team-relationships');
            relationshipsDiv.innerHTML = '<p style="text-align: center; color: #666; font-size: 0.95em; padding: 20px;">团队关系系统尚未初始化</p>';

            const scheduleDiv = document.getElementById('schedule-info');
            scheduleDiv.innerHTML = '<div class="schedule-card"><p style="text-align: center; color: #666; font-style: italic;">日程系统尚未初始化</p></div>';

            // 显示内容，隐藏加载提示
            document.getElementById('loading').style.display = 'none';
            document.getElementById('content').style.display = 'block';
        }

