# 队内关系分阶段

<%
    const members = ['蔚向晚', '岑寂', '时雨', '舒窈', '明昭雪', '空山灵', '安可乐', '泠弦'];
    const stat_data = getvar("stat_data");

    if (stat_data) {
        // 获取关系数据的简化函数
        function getRelationship(from, to) {
            const path = '偶像成员.' + from + '.队内人际关系.' + to + '[0]';
            return _.get(stat_data, path, 10);
        }

        // 构建关系网络图谱
        const relationshipMatrix = {};
        for (let member of members) {
            relationshipMatrix[member] = {};
        }

        // 填充关系矩阵
        for (let i = 0; i < members.length; i++) {
            for (let j = 0; j < members.length; j++) {
                if (i !== j) {
                    const from = members[i];
                    const to = members[j];
                    const affection = getRelationship(from, to);
                    relationshipMatrix[from][to] = affection;
                }
            }
        }

        // 简化的小团体识别函数（限制数量，避免过度复杂）
        function findSimplifiedGroups(minAffection = 40) {
            const groups = [];
            const processed = new Set();

            // 优先寻找最大的紧密团体
            for (let member of members) {
                if (processed.has(member)) continue;

                const closeConnections = [];

                // 找到与当前成员互相高好感的人
                for (let other of members) {
                    if (other !== member && 
                        relationshipMatrix[member][other] >= minAffection && 
                        relationshipMatrix[other][member] >= minAffection) {
                        closeConnections.push(other);
                    }
                }

                if (closeConnections.length === 0) continue;

                // 尝试构建最大的互相连接团体
                const group = new Set([member]);

                for (let candidate of closeConnections) {
                    if (processed.has(candidate)) continue;

                    // 检查候选人是否与团体内所有成员都有高好感
                    let canJoin = true;
                    for (let groupMember of group) {
                        if (relationshipMatrix[candidate][groupMember] < minAffection || 
                            relationshipMatrix[groupMember][candidate] < minAffection) {
                            canJoin = false;
                            break;
                        }
                    }

                    if (canJoin) {
                        group.add(candidate);
                    }
                }

                // 只记录2人以上的团体
                if (group.size >= 2) {
                    const groupArray = Array.from(group);
                    const avgAffections = [];

                    for (let i = 0; i < groupArray.length; i++) {
                        for (let j = i + 1; j < groupArray.length; j++) {
                            const member1 = groupArray[i];
                            const member2 = groupArray[j];
                            const avg = Math.round((relationshipMatrix[member1][member2] + 
                                                  relationshipMatrix[member2][member1]) / 2);
                            avgAffections.push(avg);
                        }
                    }

                    groups.push({
                        members: groupArray.sort(),
                        avgAffection: Math.round(avgAffections.reduce((a, b) => a + b, 0) / avgAffections.length),
                        size: group.size,
                        id: groupArray.sort().join('-')
                    });

                    // 标记已处理的成员
                    groupArray.forEach(m => processed.add(m));
                }
            }

            // 限制输出数量（最多3个主要团体）
            return groups
                .sort((a, b) => b.size - a.size || b.avgAffection - a.avgAffection)
                .slice(0, 3);
        }

        // 查找各种关系类型（简化版本）
        const coreGroups = findSimplifiedGroups(40);  // 核心小团体（高好感）

        // 单独处理对立关系和依附关系
        const conflictPairs = [];
        const attachmentRelations = [];
        const processedPairs = new Set();

        for (let i = 0; i < members.length; i++) {
            for (let j = i + 1; j < members.length; j++) {
                const member1 = members[i];
                const member2 = members[j];
                const pairKey = [member1, member2].sort().join('-');

                if (processedPairs.has(pairKey)) continue;

                const affection1to2 = relationshipMatrix[member1][member2];
                const affection2to1 = relationshipMatrix[member2][member1];

                // 对立关系（互相负好感）
                if (affection1to2 < 0 && affection2to1 < 0) {
                    conflictPairs.push({
                        pair: [member1, member2],
                        avg: Math.round((affection1to2 + affection2to1) / 2)
                    });
                }
                // 依附关系（单方面高好感）
                else if ((affection1to2 >= 40 && affection2to1 < 20) || 
                         (affection2to1 >= 40 && affection1to2 < 20)) {
                    const from = affection1to2 > affection2to1 ? member1 : member2;
                    const to = affection1to2 > affection2to1 ? member2 : member1;
                    const intensity = Math.max(affection1to2, affection2to1);
                    attachmentRelations.push({
                        from: from,
                        to: to,
                        intensity: intensity
                    });
                }

                processedPairs.add(pairKey);
            }
        }

        // 分析重叠成员情况
        function analyzeOverlaps(groups) {
            const memberGroupCount = {};
            const overlaps = [];

            groups.forEach((group, index) => {
                group.members.forEach(member => {
                    if (!memberGroupCount[member]) memberGroupCount[member] = [];
                    memberGroupCount[member].push(index + 1);
                });
            });

            // 找出同时属于多个团体的成员
            const bridgeMembers = Object.keys(memberGroupCount)
                .filter(member => memberGroupCount[member].length > 1)
                .map(member => ({
                    name: member,
                    groups: memberGroupCount[member]
                }));

            return { memberGroupCount, bridgeMembers };
        }

        // 输出核心小团体（多人团体优先）
        if (coreGroups.length > 0) {
            const coreOverlaps = analyzeOverlaps(coreGroups);
%>
**🌟 核心小团体**
<% coreGroups.forEach((group, index) => { %>
**团体 <%= index + 1 %>**: <%= group.members.join(' ↔ ') %> (<%= group.size %>人团体，平均好感度 <%= group.avgAffection %>)
<% }); %>
<% if (coreOverlaps.bridgeMembers.length > 0) { %>
   **🔗 桥梁成员**: <% coreOverlaps.bridgeMembers.forEach((bridge, idx) => { %><%= bridge.name %>同时属于团体<%= bridge.groups.join('、') %><%= idx < coreOverlaps.bridgeMembers.length - 1 ? '；' : '' %><% }); %>
<% } %>
   └─ **特征**: 互相信任度极高，形成紧密同盟，行动高度一致
<% if (coreOverlaps.bridgeMembers.length > 0) { %>   └─ **重叠效应**: 桥梁成员在团体间起连接作用，可能成为信息传递者或矛盾调解者<% } %>

---

<%
        }

        // 输出依附关系
        if (attachmentRelations.length > 0) {
%>
**💫 依附关系**
<% attachmentRelations.forEach((rel, index) => { %>
**依附 <%= index + 1 %>**: <%= rel.from %> → <%= rel.to %> (单向好感 <%= rel.intensity %>)
<% }); %>
   └─ **特征**: 单方面的强烈情感，可能产生"热脸贴冷屁股"的戏剧性

---

<%
        }

        // 输出对立关系
        if (conflictPairs.length > 0) {
%>
**⚡ 对立关系**
<% conflictPairs.forEach((rel, index) => { %>
**对立 <%= index + 1 %>**: <%= rel.pair.join(' ↔ ') %> (互相好感 <%= rel.avg %>)
<% }); %>
   └─ **特征**: 价值观或利益冲突，避免单独接触，团体活动中气氛紧张

---

<%
        }

        // 如果没有特殊关系
        const totalRelations = coreGroups.length + 
                              attachmentRelations.length + conflictPairs.length;

        if (totalRelations === 0) {
%>
**🎭 团队关系状态**: 目前团队内部关系相对平淡，大多数成员保持普通同事关系

---

<%
        }
    } else {
%>
*团队关系系统尚未初始化。*
<%
    }
%>

#### **团体动态应用指南**

1. **小团体行动一致性**: 同一团体成员在冲突中倾向站在同一立场，共进退
2. **跨团体互动张力**: 不同团体间存在微妙竞争或合作关系，影响整体氛围
3. **桥梁成员的复杂性**: 同时属于多个团体的成员面临忠诚度分化，可能成为：
   - **信息枢纽**: 在团体间传递消息，掌握多方情报
   - **矛盾调解者**: 利用多重身份缓解团体间紧张关系
   - **两面受敌**: 当所属团体产生冲突时，陷入进退两难的境地
4. **重叠效应的戏剧性**: 桥梁成员的选择和态度会放大或缓解团体间的矛盾
5. **依附关系的戏剧性**: 单向情感产生复杂的人际动态，容易引发误解
6. **对立关系的爆发点**: 压抑的矛盾在压力下容易公开化，可能波及相关团体

